-- Generate unique private IDs, retaining an exact old->new mapping for each
-- owner. In particular, IDs within shopping_lists.items cannot be left pointing
-- at the old shared product table.
CREATE TEMP TABLE _category_id_map (
  owner_id integer NOT NULL,
  old_id integer NOT NULL,
  new_id integer NOT NULL,
  PRIMARY KEY (owner_id, old_id)
);
