-- Remap active and saved snapshots in place, keeping quantities, names, notes,
-- order, timestamps and item_count unchanged. For an already-deleted legacy
-- product, preserve its old IDs in extra audit fields but replace its selectable
-- ID with a negative per-list tombstone. Otherwise that old ID could collide
-- with an unrelated newly generated private product ID.
UPDATE "shopping_lists" AS list
SET "items" = COALESCE((
  SELECT jsonb_agg(
    CASE
      WHEN mapped.new_id IS NOT NULL THEN jsonb_set(
        jsonb_set(entry.item, '{productId}', to_jsonb(mapped.new_id)),
        '{categoryId}', to_jsonb(mapped.new_category_id)
      )
      WHEN jsonb_typeof(entry.item) = 'object' AND entry.item ? 'productId' THEN
        entry.item || jsonb_build_object(
          'legacyProductId', entry.item->'productId',
          'legacyCategoryId', entry.item->'categoryId',
          'productId', -entry.position::integer,
          'categoryId', -entry.position::integer
        )
      ELSE entry.item
    END ORDER BY entry.position
  )
  FROM jsonb_array_elements(list.items) WITH ORDINALITY AS entry(item, position)
  LEFT JOIN _product_id_map mapped
    ON mapped.owner_id = list.user_id
    AND mapped.old_id::text = entry.item->>'productId'
), '[]'::jsonb)
WHERE jsonb_typeof(list.items) = 'array';
