-- The durable flag prevents deleted-empty catalogues from being reseeded later.
-- If the legacy catalogue was empty, leave the flag false so new requests
-- initialize from the immutable SEED_CATALOG source instead.
UPDATE "users" SET "catalog_initialized" = true
WHERE EXISTS (SELECT 1 FROM "categories");
